INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`Locale`,`OptionText`,`BoxText`) VALUES (6185,2,'ruRU','Я конфискую украденное зерно, предупрежу преступника о том, что воровство – путь к беде и разрушению, и отпущу его к семье.','') ON DUPLICATE KEY UPDATE `OptionText`=IF(`OptionText` IS NULL OR `OptionText`='',VALUES(`OptionText`),`OptionText`), `BoxText`=IF(`BoxText` IS NULL OR `BoxText`='',VALUES(`BoxText`),`BoxText`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:gossip_menu_option_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_gossip_menu_option
INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`Locale`,`OptionText`,`BoxText`) VALUES (6185,3,'ruRU','Я отдам ему столько зерна, чтобы он мог прокормить свою семью пару дней, и посоветую ему покинуть наши земли.','') ON DUPLICATE KEY UPDATE `OptionText`=IF(`OptionText` IS NULL OR `OptionText`='',VALUES(`OptionText`),`OptionText`), `BoxText`=IF(`BoxText` IS NULL OR `BoxText`='',VALUES(`BoxText`),`BoxText`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:gossip_menu_option_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_gossip_menu_option
INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`Locale`,`OptionText`,`BoxText`) VALUES (6186,0,'ruRU','Я хочу узнать, что мне уготовано судьбой!','') ON DUPLICATE KEY UPDATE `OptionText`=IF(`OptionText` IS NULL OR `OptionText`='',VALUES(`OptionText`),`OptionText`), `BoxText`=IF(`BoxText` IS NULL OR `BoxText`='',VALUES(`BoxText`),`BoxText`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:gossip_menu_option_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_gossip_menu_option
INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`Locale`,`OptionText`,`BoxText`) VALUES (6187,0,'ruRU','Я исполню веление моего господина. Его смерть будет долгой и мучительной, ибо он совершил преступление против моего народа.','') ON DUPLICATE KEY UPDATE `OptionText`=IF(`OptionText` IS NULL OR `OptionText`='',VALUES(`OptionText`),`OptionText`), `BoxText`=IF(`BoxText` IS NULL OR `BoxText`='',VALUES(`BoxText`),`BoxText`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:gossip_menu_option_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_gossip_menu_option
INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`Locale`,`OptionText`,`BoxText`) VALUES (6187,1,'ruRU','Я казню его, как приказал мой господин, но сделаю это по возможности быстро и безболезненно. Правосудие правосудием, но зверства тут ни к чему.','') ON DUPLICATE KEY UPDATE `OptionText`=IF(`OptionText` IS NULL OR `OptionText`='',VALUES(`OptionText`),`OptionText`), `BoxText`=IF(`BoxText` IS NULL OR `BoxText`='',VALUES(`BoxText`),`BoxText`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:gossip_menu_option_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_gossip_menu_option
INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`Locale`,`OptionText`,`BoxText`) VALUES (6187,2,'ruRU','Я рискну собственной жизнью и освобожу его, чтобы он мог доказать свою невиновность. Я помогу другу всем, чем смогу.','') ON DUPLICATE KEY UPDATE `OptionText`=IF(`OptionText` IS NULL OR `OptionText`='',VALUES(`OptionText`),`OptionText`), `BoxText`=IF(`BoxText` IS NULL OR `BoxText`='',VALUES(`BoxText`),`BoxText`);
