INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`Locale`,`OptionText`,`BoxText`) VALUES (6208,0,'ruRU','Я выступлю против его недостойного поведения, чтобы защитить честь моего господина, пусть даже это поставит под угрозу наши переговоры.','') ON DUPLICATE KEY UPDATE `OptionText`=IF(`OptionText` IS NULL OR `OptionText`='',VALUES(`OptionText`),`OptionText`), `BoxText`=IF(`BoxText` IS NULL OR `BoxText`='',VALUES(`BoxText`),`BoxText`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:gossip_menu_option_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_gossip_menu_option
INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`Locale`,`OptionText`,`BoxText`) VALUES (6208,1,'ruRU','Я проигнорирую оскорбление – пусть правитель как следует обдумает последствия своих слов. Вернувшись, я немедля сообщу своему господину об оскорблении.','') ON DUPLICATE KEY UPDATE `OptionText`=IF(`OptionText` IS NULL OR `OptionText`='',VALUES(`OptionText`),`OptionText`), `BoxText`=IF(`BoxText` IS NULL OR `BoxText`='',VALUES(`BoxText`),`BoxText`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:gossip_menu_option_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_gossip_menu_option
INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`Locale`,`OptionText`,`BoxText`) VALUES (6208,2,'ruRU','Я проигнорирую оскорбление. Мне нужно сохранить мир любой ценой, а потому я не стану сообщать об этом инциденте. Это всего лишь оскорбление, а не объявление войны.','') ON DUPLICATE KEY UPDATE `OptionText`=IF(`OptionText` IS NULL OR `OptionText`='',VALUES(`OptionText`),`OptionText`), `BoxText`=IF(`BoxText` IS NULL OR `BoxText`='',VALUES(`BoxText`),`BoxText`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:gossip_menu_option_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_gossip_menu_option
INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`Locale`,`OptionText`,`BoxText`) VALUES (6209,0,'ruRU','Я выступлю против принятия моего брата в орден, даже осознавая, что навсегда испорчу с ним отношения. Он может быть опасен для себя самого и окружающих. А надеяться, что со временем он изменится к лучшему, очень рискованно.','') ON DUPLICATE KEY UPDATE `OptionText`=IF(`OptionText` IS NULL OR `OptionText`='',VALUES(`OptionText`),`OptionText`), `BoxText`=IF(`BoxText` IS NULL OR `BoxText`='',VALUES(`BoxText`),`BoxText`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:gossip_menu_option_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_gossip_menu_option
INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`Locale`,`OptionText`,`BoxText`) VALUES (6209,1,'ruRU','Я попрошу принять брата в орден, несмотря на риск. С моей помощью он быстро освоится в ордене и станет образцом для подражания.','') ON DUPLICATE KEY UPDATE `OptionText`=IF(`OptionText` IS NULL OR `OptionText`='',VALUES(`OptionText`),`OptionText`), `BoxText`=IF(`BoxText` IS NULL OR `BoxText`='',VALUES(`BoxText`),`BoxText`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:gossip_menu_option_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_gossip_menu_option
INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`Locale`,`OptionText`,`BoxText`) VALUES (6209,2,'ruRU','Я изобрету хитрый способ не допустить своего брата в орден и сделаю это так, что он и не догадается. Тем самым я сохраню мир в семье и порядок в ордене.','') ON DUPLICATE KEY UPDATE `OptionText`=IF(`OptionText` IS NULL OR `OptionText`='',VALUES(`OptionText`),`OptionText`), `BoxText`=IF(`BoxText` IS NULL OR `BoxText`='',VALUES(`BoxText`),`BoxText`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:gossip_menu_option_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_gossip_menu_option
INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`Locale`,`OptionText`,`BoxText`) VALUES (6210,1,'ruRU','Я покажу господину ухо зверя, доказав, что оно пало от моей руки. Часть полученной награды я отдам бедному рыцарю, чтобы помочь его семье.','') ON DUPLICATE KEY UPDATE `OptionText`=IF(`OptionText` IS NULL OR `OptionText`='',VALUES(`OptionText`),`OptionText`), `BoxText`=IF(`BoxText` IS NULL OR `BoxText`='',VALUES(`BoxText`),`BoxText`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:gossip_menu_option_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_gossip_menu_option
INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`Locale`,`OptionText`,`BoxText`) VALUES (6210,2,'ruRU','Я умолчу о своем подвиге. Пусть рыцарь заберет награду – ему она нужнее, чем мне.','') ON DUPLICATE KEY UPDATE `OptionText`=IF(`OptionText` IS NULL OR `OptionText`='',VALUES(`OptionText`),`OptionText`), `BoxText`=IF(`BoxText` IS NULL OR `BoxText`='',VALUES(`BoxText`),`BoxText`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:gossip_menu_option_locale
INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`Locale`,`OptionText`,`BoxText`) VALUES (6211,0,'ruRU','Я бы хотел получить такое предсказание. В моих сумках найдется место.','') ON DUPLICATE KEY UPDATE `OptionText`=IF(`OptionText` IS NULL OR `OptionText`='',VALUES(`OptionText`),`OptionText`), `BoxText`=IF(`BoxText` IS NULL OR `BoxText`='',VALUES(`BoxText`),`BoxText`);
