INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`Locale`,`OptionText`,`BoxText`) VALUES (7401,0,'ruRU','У нас много общего, ночной эльф. Я не могу отделаться от мысли, что, возможно, вместе нас свела судьба. Позволь мне помочь тебе, Коулен. Пусть мой народ поможет тоже. Мы все исправим. Я обещаю.','') ON DUPLICATE KEY UPDATE `OptionText`=IF(`OptionText` IS NULL OR `OptionText`='',VALUES(`OptionText`),`OptionText`), `BoxText`=IF(`BoxText` IS NULL OR `BoxText`='',VALUES(`BoxText`),`BoxText`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:gossip_menu_option_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_gossip_menu_option
INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`Locale`,`OptionText`,`BoxText`) VALUES (7402,0,'ruRU','Боюсь, что мои люди отчасти виноваты в этих несчастьях. Мы – беженцы, покинувшие свои дома в поисках спасения от Пылающего Легиона. Эта трагедия – результат нашей недавней эвакуации. Наш корабль разбился, и вот его обломки.','') ON DUPLICATE KEY UPDATE `OptionText`=IF(`OptionText` IS NULL OR `OptionText`='',VALUES(`OptionText`),`OptionText`), `BoxText`=IF(`BoxText` IS NULL OR `BoxText`='',VALUES(`BoxText`),`BoxText`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:gossip_menu_option_locale
INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`Locale`,`OptionText`,`BoxText`) VALUES (7403,0,'ruRU','Я пришел не затем, чтобы убить тебя, ночной эльф. И боги не позволят этому случиться...','') ON DUPLICATE KEY UPDATE `OptionText`=IF(`OptionText` IS NULL OR `OptionText`='',VALUES(`OptionText`),`OptionText`), `BoxText`=IF(`BoxText` IS NULL OR `BoxText`='',VALUES(`BoxText`),`BoxText`);
