INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`Locale`,`OptionText`,`BoxText`) VALUES (7426,0,'ruRU','Все кончено, Искр. Адмирал знает, что Альянс предал ты. Теперь либо ты будешь сотрудничать со мной и расскажешь все, что знаешь, либо мы решим дело в кулачном бою.','') ON DUPLICATE KEY UPDATE `OptionText`=IF(`OptionText` IS NULL OR `OptionText`='',VALUES(`OptionText`),`OptionText`), `BoxText`=IF(`BoxText` IS NULL OR `BoxText`='',VALUES(`BoxText`),`BoxText`);
