INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`Locale`,`OptionText`,`BoxText`) VALUES (7531,0,'ruRU','Я в плену – что не ясно? Дренейские отродья схватили меня у выхода из Солнечных Ворот. Они разрушили пульты управления и уничтожили ворота. Солнечный король будет очень недоволен таким поворотом событий.','') ON DUPLICATE KEY UPDATE `OptionText`=IF(`OptionText` IS NULL OR `OptionText`='',VALUES(`OptionText`),`OptionText`), `BoxText`=IF(`BoxText` IS NULL OR `BoxText`='',VALUES(`BoxText`),`BoxText`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:gossip_menu_option_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_gossip_menu_option
INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`Locale`,`OptionText`,`BoxText`) VALUES (7533,0,'ruRU','Да, и вы мне поверили. Спасибо за информацию, эльф крови. Вы не представляете, как помогли нам.','') ON DUPLICATE KEY UPDATE `OptionText`=IF(`OptionText` IS NULL OR `OptionText`='',VALUES(`OptionText`),`OptionText`), `BoxText`=IF(`BoxText` IS NULL OR `BoxText`='',VALUES(`BoxText`),`BoxText`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:gossip_menu_option_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_gossip_menu_option
INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`Locale`,`OptionText`,`BoxText`) VALUES (7534,0,'ruRU','Векторная Спираль огромна. Надеюсь, у нас там больше одной мерзости на охране многочисленных слабых мест.','') ON DUPLICATE KEY UPDATE `OptionText`=IF(`OptionText` IS NULL OR `OptionText`='',VALUES(`OptionText`),`OptionText`), `BoxText`=IF(`BoxText` IS NULL OR `BoxText`='',VALUES(`BoxText`),`BoxText`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:gossip_menu_option_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_gossip_menu_option
INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`Locale`,`OptionText`,`BoxText`) VALUES (7535,0,'ruRU','Сиронас – эредар... Я имею в виду, да, это очевидно.','') ON DUPLICATE KEY UPDATE `OptionText`=IF(`OptionText` IS NULL OR `OptionText`='',VALUES(`OptionText`),`OptionText`), `BoxText`=IF(`BoxText` IS NULL OR `BoxText`='',VALUES(`BoxText`),`BoxText`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:gossip_menu_option_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_gossip_menu_option
INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`Locale`,`OptionText`,`BoxText`) VALUES (7536,0,'ruRU','Невероятно. Как Сиронас удалось совершить такое?','') ON DUPLICATE KEY UPDATE `OptionText`=IF(`OptionText` IS NULL OR `OptionText`='',VALUES(`OptionText`),`OptionText`), `BoxText`=IF(`BoxText` IS NULL OR `BoxText`='',VALUES(`BoxText`),`BoxText`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:gossip_menu_option_locale
INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`Locale`,`OptionText`,`BoxText`) VALUES (7537,0,'ruRU','Ах да, Сиронас. Я почти забыл, что там была Сиронас. Я служил под началом Сиронас там, в Запределье. Тем не менее я не слышал об этой мерзости – проклятые дренеи схватили меня до того, как я смог полностью материализоваться в этом мире.','') ON DUPLICATE KEY UPDATE `OptionText`=IF(`OptionText` IS NULL OR `OptionText`='',VALUES(`OptionText`),`OptionText`), `BoxText`=IF(`BoxText` IS NULL OR `BoxText`='',VALUES(`BoxText`),`BoxText`);
