INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`Locale`,`OptionText`,`BoxText`) VALUES (7976,0,'ruRU','Я немедленно вернусь в Азерот, Великая Мать.','') ON DUPLICATE KEY UPDATE `OptionText`=IF(`OptionText` IS NULL OR `OptionText`='',VALUES(`OptionText`),`OptionText`), `BoxText`=IF(`BoxText` IS NULL OR `BoxText`='',VALUES(`BoxText`),`BoxText`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:gossip_menu_option_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_gossip_menu_option
INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`Locale`,`OptionText`,`BoxText`) VALUES (7977,0,'ruRU','Это мой вождь, Великая Мать. Предводитель моего народа. Из моего мира. Он... Он сын Дуротана. Он твой внук.','') ON DUPLICATE KEY UPDATE `OptionText`=IF(`OptionText` IS NULL OR `OptionText`='',VALUES(`OptionText`),`OptionText`), `BoxText`=IF(`BoxText` IS NULL OR `BoxText`='',VALUES(`BoxText`),`BoxText`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:gossip_menu_option_locale
INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`Locale`,`OptionText`,`BoxText`) VALUES (7978,0,'ruRU','Великая Мать, мне не выпала такая честь. Дуротан умер задолго до моего рождения, но подвиги его известны всем в моем мире. Орки Азерота проживают в Дуротаре – месте, что названо в честь твоего сына. И... *Вы делаете краткую паузу, чтобы отдышаться и обдумать слова, которые собираетесь сказать Великой Матери.*','') ON DUPLICATE KEY UPDATE `OptionText`=IF(`OptionText` IS NULL OR `OptionText`='',VALUES(`OptionText`),`OptionText`), `BoxText`=IF(`BoxText` IS NULL OR `BoxText`='',VALUES(`BoxText`),`BoxText`);
