INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`Locale`,`OptionText`,`BoxText`) VALUES (11741,0,'ruRU','Бодунья, мне придется попросить тебя об огромном одолжении. Нужно отрезать твою голову, чтобы доказать мою верность пиратам Кровавого Паруса. Тогда я смогу проникнуть в их ряды и, если повезет, узнать их истинные намерения.\r\n\r\nПиратская Бухта нуждается в тебе, Бодунья... Сейчас ты нужна нам как никогда.','') ON DUPLICATE KEY UPDATE `OptionText`=IF(`OptionText` IS NULL OR `OptionText`='',VALUES(`OptionText`),`OptionText`), `BoxText`=IF(`BoxText` IS NULL OR `BoxText`='',VALUES(`BoxText`),`BoxText`);
